import numpy as np
from scipy.optimize import minimize

def objective(p):
    x, y, z = p
    return (x**2 + y**2 + z**2 - 3)**2 + (x*y**3 + y*z**3 + z*x**3 - 3)**2

solutions = []
# Grid of starting points
s = np.linspace(-1.8, 1.8, 15)
for sx in s:
    for sy in s:
        for sz in s:
            res = minimize(objective, [sx, sy, sz], tol=1e-12)
            if res.fun < 1e-9:
                # Round to avoid duplicates
                sol = tuple(np.round(res.x, 8))
                solutions.append(sol)

unique_solutions = set(solutions)
print(f"Found {len(unique_solutions)} candidate solutions.")
for sol in unique_solutions:
