import numpy as np
from scipy.optimize import minimize

def objective(p):
    x, y, z = p
    return (x**2 + y**2 + z**2 - 3)**2 + (x*y**3 + y*z**3 + z*x**3 - 3)**2

def find_solutions():
    solutions = []
    s = np.linspace(-1.8, 1.8, 15)
    for sx in s:
        for sy in s:
            for sz in s:
                res = minimize(objective, [sx, sy, sz], tol=1e-12)
                if res.fun < 1e-12:
                    solutions.append(res.x)

    # Cluster solutions
    unique_solutions = []
    for sol in solutions:
        is_new = True
        for usol in unique_solutions:
            if np.allclose(sol, usol, atol=1e-5):
                is_new = False
                break
        if is_new:
            unique_solutions.append(sol)
    return unique_solutions

unique_sols = find_solutions()
print(f"Found {len(unique_sols)} unique solutions.")
for i, sol in enumerate(unique_sols):
    print(f"{i}: {sol}")

